#include "reference_owned_scene.h"
#include <iostream>
int main(){try{static_assert(sizeof(void*)==8,"x64 required");RecoveredOwnedSceneCandidate scene;auto&a=scene.create({1,0,0,0});auto&b=scene.create({2,0,0,0});auto&attr=scene.attach(a,0x81,{b.record.handle});scene.attach(a,0x81,{b.record.handle});a.registration.state=3;b.registration.state=3;scene.queues.registration.append(a.record.handle);scene.queues.registration.append(0xffffffff);scene.queues.registration.append(a.record.handle);unsigned calls=0;scene.dispatchResolveQueue([&](auto*e){if(e!=&a)throw std::runtime_error("wrong owner");if(calls==0&&(!(e->registration.state&1)||!(attr.flags&0x80)))throw std::runtime_error("cleanup before callback");if(calls==1&&((e->registration.state&1)||(attr.flags&0x80)))throw std::runtime_error("cleanup after callback");scene.queues.registration.append(b.record.handle);++calls;});if(calls!=2||!scene.queues.registration.handles.empty()||a.registration.state!=2||b.registration.state!=3)throw std::runtime_error("dispatch state");for(auto*p=a.attributes;p;p=p->next)if(p->flags&0x80)throw std::runtime_error("attribute flag remains");a.registration.state=0;markElementMutation(a.registration.state,a.record.handle,[&](uint32_t h){scene.queues.registration.append(h);});markElementMutation(a.registration.state,a.record.handle,[&](uint32_t h){scene.queues.registration.append(h);});if(scene.queues.registration.handles.size()!=1)throw std::runtime_error("duplicate mark");scene.dispatchResolveQueue([&](auto*e){if(e!=&a)throw std::runtime_error("remark resolve");++calls;});if(calls!=3||a.registration.state!=2)throw std::runtime_error("remark cleanup");std::cout<<"owned resolve queue integration passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
